using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Models;
namespace RaceDay.Api.Data;
public sealed class RaceDayContext(DbContextOptions<RaceDayContext> options) : DbContext(options) {
 public DbSet<Role> Roles => Set<Role>(); public DbSet<User> Users => Set<User>(); public DbSet<Event> Events => Set<Event>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<Enrolment> Enrolments => Set<Enrolment>(); public DbSet<Result> Results => Set<Result>();
 protected override void OnModelCreating(ModelBuilder b) {
  b.Entity<Role>().ToTable("Roles").HasKey(x=>x.RoleId); b.Entity<Role>().Property(x=>x.RoleName).HasMaxLength(20).IsRequired(); b.Entity<Role>().HasIndex(x=>x.RoleName).IsUnique();
  b.Entity<User>().ToTable("Users").HasKey(x=>x.UserId); b.Entity<User>().Property(x=>x.FullName).HasMaxLength(100).IsRequired(); b.Entity<User>().Property(x=>x.Email).HasMaxLength(150).IsRequired(); b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<User>().Property(x=>x.PasswordHash).HasMaxLength(255).IsRequired(); b.Entity<User>().HasOne(x=>x.Role).WithMany(x=>x.Users).HasForeignKey(x=>x.RoleId);
  b.Entity<Event>().ToTable("Events").HasKey(x=>x.EventId); b.Entity<Event>().Property(x=>x.EventName).HasMaxLength(150).IsRequired(); b.Entity<Event>().Property(x=>x.Description).HasMaxLength(1000); b.Entity<Event>().Property(x=>x.Location).HasMaxLength(200).IsRequired(); b.Entity<Event>().Property(x=>x.RouteInfo).HasMaxLength(500); b.Entity<Event>().HasOne(x=>x.Organiser).WithMany(x=>x.Events).HasForeignKey(x=>x.OrganiserId).OnDelete(DeleteBehavior.Restrict);
  b.Entity<Category>().ToTable("Categories").HasKey(x=>x.CategoryId); b.Entity<Category>().Property(x=>x.CategoryName).HasMaxLength(50).IsRequired(); b.Entity<Category>().Property(x=>x.DistanceKm).HasPrecision(5,2); b.Entity<Category>().HasOne(x=>x.Event).WithMany(x=>x.Categories).HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Cascade);
  b.Entity<Enrolment>().ToTable("Enrolments").HasKey(x=>x.EnrolmentId); b.Entity<Enrolment>().Property(x=>x.Status).HasMaxLength(20).IsRequired(); b.Entity<Enrolment>().HasIndex(x=>new{x.ParticipantId,x.CategoryId}).IsUnique(); b.Entity<Enrolment>().HasOne(x=>x.Participant).WithMany(x=>x.Enrolments).HasForeignKey(x=>x.ParticipantId).OnDelete(DeleteBehavior.Restrict); b.Entity<Enrolment>().HasOne(x=>x.Category).WithMany(x=>x.Enrolments).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Cascade);
  b.Entity<Result>().ToTable("Results").HasKey(x=>x.ResultId); b.Entity<Result>().HasIndex(x=>x.EnrolmentId).IsUnique(); b.Entity<Result>().HasOne(x=>x.Enrolment).WithOne(x=>x.Result).HasForeignKey<Result>(x=>x.EnrolmentId).OnDelete(DeleteBehavior.Cascade); b.Entity<Result>().HasOne(x=>x.RecordedBy).WithMany().HasForeignKey(x=>x.RecordedByUserId).OnDelete(DeleteBehavior.Restrict);
 }
}
